async function refreshSpeeds(){const rows=(await DB.all('speedTests')).sort((a,b)=>Date.parse(a.createdAt)-Date.parse(b.createdAt));const list=$('#speedList');if(list)list.innerHTML=rows.slice(-8).reverse().map(r=>`<div class="item"><strong>${esc(r.provider)}</strong> · ${fmt(r.down)}/${fmt(r.up)} Mbps · ${fmt(r.latency)} ms<div class="small muted">${new Date(r.createdAt).toLocaleString()} · ${esc(r.connection)} · ${esc(r.place)}</div></div>`).join('')||'<p class="muted">No local observations yet.</p>';drawSpeed(rows.slice(-24))}
function drawSpeed(rows){const c=$('#speedChart');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const style=getComputedStyle(document.documentElement),line=style.getPropertyValue('--line'),ink=style.getPropertyValue('--ink'),accent=style.getPropertyValue('--accent');ctx.strokeStyle=line;ctx.fillStyle=ink;ctx.font='12px system-ui';for(let i=0;i<5;i++){const y=20+i*(h-45)/4;ctx.beginPath();ctx.moveTo(45,y);ctx.lineTo(w-15,y);ctx.stroke()}if(!rows.length){ctx.fillText('No speed observations yet',55,45);return}const max=Math.max(10,...rows.flatMap(r=>[+r.down,+r.up]));const x=i=>45+i*(w-70)/Math.max(1,rows.length-1),y=v=>h-25-(+v/max)*(h-55);ctx.strokeStyle=accent;ctx.lineWidth=3;ctx.beginPath();rows.forEach((r,i)=>i?ctx.lineTo(x(i),y(r.down)):ctx.moveTo(x(i),y(r.down)));ctx.stroke();ctx.setLineDash([6,4]);ctx.beginPath();rows.forEach((r,i)=>i?ctx.lineTo(x(i),y(r.up)):ctx.moveTo(x(i),y(r.up)));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=ink;ctx.fillText(`max ${max.toFixed(0)} Mbps · solid=down, dashed=up`,50,15)}
