function bindAI(){let selected=new Set();$$('[data-ai-domain]').forEach(b=>b.onclick=()=>{b.classList.toggle('selected');b.classList.contains('selected')?selected.add(b.dataset.aiDomain):selected.delete(b.dataset.aiDomain)});$('#loadCatalog').onclick=async()=>{try{$('#aiProgress').textContent='Loading WebLLM runtime/catalog…';const ms=await AI.models();$('#modelSelect').innerHTML=ms.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('');$('#aiProgress').textContent=`${ms.length} prebuilt model records available. Choose a model appropriate for your device memory.`}catch(e){$('#aiProgress').textContent='Could not load WebLLM catalog: '+e.message}};$('#loadModel').onclick=async()=>{const id=$('#modelSelect').value;if(!id||id.includes('catalog'))return;try{$('#aiProgress').textContent='Initializing…';await AI.loadModel(id,p=>{$('#aiProgress').textContent=p.text||`${Math.round((p.progress||0)*100)}%`});$('#aiProgress').textContent='Model loaded locally.'}catch(e){$('#aiProgress').textContent='Model load failed: '+e.message}};$('#unloadModel').onclick=async()=>{await AI.unload();$('#aiProgress').textContent='Model unloaded.'};const input=()=>{const f=$('#aiForm'),o=Object.fromEntries(new FormData(f));return {...o,domains:[...selected]}};$('#fallbackPlan').onclick=()=>{$('#aiOutput').textContent=AI.fallbackPlan(input())};$('#aiForm').onsubmit=async e=>{e.preventDefault();const i=input(),sources=state.texas.facts.filter(f=>['bead-summary','boot','digital-opportunity','fcc-map','rhcf','erate','workforce'].includes(f.id)).map(f=>`${f.title}: ${f.value} (${f.publisher}, ${f.date})`).join('\n');const system=`You are a neutral Texas connectivity planning assistant running locally in the user's browser. Distinguish sourced facts from assumptions and modeled scenarios. Do not invent grants, deadlines, coverage or provider performance. Treat cross-domain benefits as pathways, not guaranteed causal outcomes. Current curated source notes:\n${sources}`;try{$('#aiOutput').textContent='Generating locally…';const out=await AI.ask([{role:'system',content:system},{role:'user',content:`Create a cross-domain plan for ${i.geography}. Problem: ${i.problem}. Stakeholders: ${i.stakeholders}. Domains: ${i.domains.join(', ')}. Include verification steps, owners, dependencies, resilience, accessibility, privacy, 30/60/90-day actions and uncertainty.`}]);$('#aiOutput').textContent=out}catch(err){$('#aiOutput').textContent='Local model unavailable: '+err.message+'\n\n'+AI.fallbackPlan(i)}}}
