function openSettings(){const p=$('#settings');p.hidden=false;p.innerHTML=`<h2>Settings</h2><div class="settingsRow"><span>Theme</span><select id="setTheme"><option value="dark">Dark</option><option value="light">Light</option></select></div><div class="settingsRow"><span>High contrast</span><input id="setContrast" type="checkbox"></div><div class="settingsRow"><span>Motion</span><input id="setMotion" type="checkbox"></div><div class="settingsRow"><span>Text size</span><input id="setFont" type="range" min=".9" max="1.35" step=".05"></div><div class="settingsRow"><span>Opportunity HUD</span><input id="setHud" type="checkbox"></div><p class="small muted">No analytics or telemetry are embedded. Collaboration and WebLLM network access are user-triggered.</p><div class="actions"><button class="btn" id="closeSettings">Close</button><button class="btn" data-route-settings="data">Data controls</button></div>`;$('#setTheme').value=state.prefs.theme;$('#setContrast').checked=state.prefs.contrast;$('#setMotion').checked=state.prefs.motion;$('#setFont').value=state.prefs.font;$('#setHud').checked=state.prefs.hud;$('#setTheme').onchange=e=>{state.prefs.theme=e.target.value;savePrefs()};$('#setContrast').onchange=e=>{state.prefs.contrast=e.target.checked;savePrefs()};$('#setMotion').onchange=e=>{state.prefs.motion=e.target.checked;savePrefs()};$('#setFont').oninput=e=>{state.prefs.font=+e.target.value;savePrefs()};$('#setHud').onchange=e=>{state.prefs.hud=e.target.checked;savePrefs()};$('#closeSettings').onclick=()=>p.hidden=true;$('[data-route-settings]').onclick=()=>{p.hidden=true;go('data')}}
